/* ============================================================
   UI base layer — "คำศัพท์กลาง" ที่แมป token -> Tailwind
   ค่าจริง (สีของแต่ละแบรนด์) อยู่ในไฟล์ token ของแบรนด์ ต้อง @import ตามหลังไฟล์นี้
   ============================================================ */

/* เปิดใช้ variant dark:... เมื่อมี class .dark บน <html> */
@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);

  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);

  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);

  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  /* พื้นผิวของ Alert แบบมีสี — ชุดเดียวกับ --card คือ พื้น + ตัวอักษร + เส้นขอบ
     ทุกตัวเป็นสีทึบ ไม่มี opacity เพื่อให้ยกไปเป็น variable ใน Figma ได้ตรง ๆ
     ใส่ fallback ไว้ แบรนด์เก่าที่ยังไม่ประกาศจะไม่พัง */
  --color-warning: var(--warning, var(--card));
  --color-warning-foreground: var(--warning-foreground, var(--foreground));
  --color-warning-border: var(--warning-border, var(--border));

  --color-danger: var(--danger, var(--card));
  --color-danger-foreground: var(--danger-foreground, var(--destructive));
  --color-danger-border: var(--danger-border, var(--border));

  --color-brand: var(--brand, var(--card));

  /* สถานะ success (พื้นอ่อน / ตัวอักษร / เส้นขอบ) + สีทึบของ badge */
  --color-success: var(--success, var(--card));
  --color-success-foreground: var(--success-foreground, var(--foreground));
  --color-success-border: var(--success-border, var(--border));
  --color-success-solid: var(--success-solid, var(--primary));
  --color-success-solid-foreground: var(--success-solid-foreground, var(--primary-foreground));
  --color-success-solid-hover: var(--success-solid-hover, var(--primary-hover));

  --color-warning-solid: var(--warning-solid, var(--warning));
  --color-warning-solid-foreground: var(--warning-solid-foreground, var(--warning-foreground));
  --color-warning-solid-hover: var(--warning-solid-hover, var(--warning));

  /* สีตอน hover ของพื้นผิวที่มีสี — ใช้แทนการลด opacity */
  --color-primary-hover: var(--primary-hover);
  --color-secondary-hover: var(--secondary-hover);
  --color-accent-hover: var(--accent-hover);
  --color-destructive-hover: var(--destructive-hover);

  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --font-sans: var(--font-sans);
}

@layer base {
  * {
    border-color: var(--border);
    outline-color: color-mix(in oklab, var(--ring) 50%, transparent);
  }
  body {
    background-color: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
  }
}

/* ============================================================
   Brand: BLUE  (สีน้ำเงิน + ฟอนต์ IBM Plex Sans Thai)
   scope ด้วย [data-brand="blue"]  ·  .dark = โหมดมืด
   แก้ค่าตรงนี้ = เปลี่ยนทั้งแบรนด์ (component ไม่ต้องแตะ)
   ============================================================ */

[data-brand="blue"] {
  --background: hsl(0 0% 100%);
  --foreground: hsl(222 47% 11%);

  --card: hsl(0 0% 100%);
  --card-foreground: hsl(222 47% 11%);

  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(222 47% 11%);

  --primary: hsl(221 83% 53%);
  --primary-foreground: hsl(0 0% 100%);

  --secondary: hsl(210 40% 96%);
  --secondary-foreground: hsl(222 47% 11%);

  --muted: hsl(210 40% 96%);
  --muted-foreground: hsl(215 16% 47%);

  --accent: hsl(210 40% 96%);
  --accent-foreground: hsl(222 47% 11%);

  --destructive: hsl(0 72% 51%);
  --destructive-foreground: hsl(0 0% 100%);

  /* สถานะ hover — โหมดสว่างให้ "เข้มขึ้น" (ลดค่า L)
     อย่าใช้วิธีลด opacity แทน เพราะบนพื้นสว่างมันจะจางลงไม่ใช่เข้มขึ้น */
  --primary-hover: hsl(221 83% 48%);
  --secondary-hover: hsl(210 40% 93%);
  --accent-hover: hsl(210 40% 93%);
  --destructive-hover: hsl(0 72% 46%);


  /* พื้นผิวของ Alert แบบมีสี — ชุดเดียวกับ --card / --sidebar
     คือ <ชื่อพื้นผิว> + -foreground + -border

     ทุกค่าเป็น "สีทึบ" ไม่ใช่สีจางทับพื้น เพราะ Figma ผูก opacity ไว้กับ variable
     ไม่ได้ ถ้าใช้สีจาง คนออกแบบต้องมาตั้ง opacity เองทุกครั้ง และต้องตั้งคนละค่า
     ในโหมดสว่างกับโหมดมืด ซึ่ง Figma สลับให้ตามโหมดไม่ได้
     ค่าที่ใส่ไว้คือค่าที่วัดจากเบราว์เซอร์ตอนที่ยังใช้สีจางทับพื้น --card
     หน้าตาจึงเหมือนเดิมเป๊ะ แค่เปลี่ยนวิธีเก็บค่า

     --warning ตรงกับ amber-50 / amber-900 / amber-200 ของ Tailwind เป๊ะ
     --danger  ใช้กับ Alert variant="destructive" ที่ชื่อไม่ตรงกันเพราะ
               --destructive ถูกจองไว้ให้ปุ่มพื้นทึบแล้ว
     --brand   ใช้ --primary เป็นเส้นขอบ และ --foreground เป็นตัวอักษร
               จึงไม่ต้องมี --brand-border / --brand-foreground */
  --warning: hsl(48 100% 96%);
  --warning-foreground: hsl(22 78% 26%);
  --warning-border: hsl(48 97% 77%);

  --danger: hsl(0 69.2% 94.9%);
  --danger-foreground: hsl(0 70% 36%);
  --danger-border: hsl(0 71.1% 85.1%);

  --brand: hsl(222 83.3% 97.6%);


  /* สถานะ success + สีทึบของ badge — อิงสเกล Radix (green / amber)
     ค่าเหมือนกันทุกแบรนด์เหมือน --destructive เพราะเป็นสีความหมาย ไม่ใช่สีแบรนด์

     ── ทำไมเขียวสดถึงคู่กับตัวอักษรสีเข้ม ไม่ใช่ขาว ──
     เขียวสว่างกว่าแดงกับน้ำเงินมากในสายตามนุษย์ (สัมประสิทธิ์ 0.7152 เทียบกับ
     0.2126 และ 0.0722) เขียวที่ "ดูสด" จึงสว่างเกินกว่าจะวางตัวอักษรขาวได้
     วัดแล้ว: green-500 กับขาว = 2.30 · Radix green-9 กับขาว = 3.09 ตกทั้งคู่
     ถ้าจะใช้ตัวอักษรขาวต้องกดเขียวให้เข้มจนหม่น เลยเลือกทางกลับกัน
     คือใช้เขียวสด (green-500 / green-400) คู่ตัวอักษรเขียวเข้ม ได้ 5.76 กับ 7.61
     เป็นวิธีเดียวกับที่ใช้กับ amber ซึ่งสว่างด้วยเหตุผลเดียวกัน

     ห้ามใช้ emerald-500 (#10B77F) เป็นสี success เด็ดขาด เพราะเป็นค่าเดียวกับ
     --primary ของแบรนด์เขียวเป๊ะ ป้าย success จะกลืนกับป้ายแบรนด์
     green-500 ห่างจากแบรนด์เขียว 18 องศาบนวงล้อสี จึงแยกออกจากกันได้ */
  --success: #ecfdef;
  --success-foreground: #068419;
  --success-border: #a8f0b3;
  --success-solid: #068919;
  --success-solid-foreground: #ffffff;
  --success-solid-hover: #057115;

  --warning-solid: hsl(43 100% 62%);
  --warning-solid-foreground: hsl(22 78% 20%);
  --warning-solid-hover: hsl(43 100% 55%);

  --border: hsl(214 32% 91%);
  --input: hsl(214 32% 91%);
  --ring: hsl(221 83% 53%);

  --chart-1: hsl(221 83% 53%);
  --chart-2: hsl(160 60% 45%);
  --chart-3: hsl(30 80% 55%);
  --chart-4: hsl(280 65% 60%);
  --chart-5: hsl(340 75% 55%);

  --sidebar: hsl(0 0% 98%);
  --sidebar-foreground: hsl(222 47% 11%);
  --sidebar-primary: hsl(221 83% 53%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(210 40% 96%);
  --sidebar-accent-foreground: hsl(222 47% 11%);
  --sidebar-border: hsl(214 32% 91%);
  --sidebar-ring: hsl(221 83% 53%);
}

[data-brand="blue"].dark {
  --background: hsl(222 47% 8%);
  --foreground: hsl(210 40% 98%);

  --card: hsl(222 47% 11%);
  --card-foreground: hsl(210 40% 98%);

  --popover: hsl(222 47% 11%);
  --popover-foreground: hsl(210 40% 98%);

  --primary: hsl(217 91% 60%);
  --primary-foreground: hsl(222 47% 11%);

  --secondary: hsl(217 33% 18%);
  --secondary-foreground: hsl(210 40% 98%);

  --muted: hsl(217 33% 18%);
  --muted-foreground: hsl(215 20% 65%);

  --accent: hsl(217 33% 18%);
  --accent-foreground: hsl(210 40% 98%);

  --destructive: hsl(0 63% 45%);
  --destructive-foreground: hsl(0 0% 98%);

  /* โหมดมืดกลับด้าน — hover ให้ "สว่างขึ้น" เพื่อให้เด่นขึ้นเหมือนกัน */
  --primary-hover: hsl(217 91% 65%);
  --secondary-hover: hsl(217 33% 22%);
  --accent-hover: hsl(217 33% 22%);
  --destructive-hover: hsl(0 63% 50%);


  /* โหมดมืดสลับหัวท้าย — warning พื้นเป็น amber-950 ตัวอักษรเป็น amber-50 */
  /* amber-950 ของ Tailwind (#451A03) อยู่ที่เฉด 21 ซึ่งตาคนอ่านว่า "น้ำตาลแดง"
     ไม่ใช่เหลือง ย้ายมาเฉด 47 ให้เป็นเหลืองเข้มจริง ๆ ในโหมดมืด */
  --warning: hsl(47 85% 13%);
  --warning-foreground: hsl(48 100% 96%);
  --warning-border: hsl(45 70% 26%);

  /* ค่าเดิมได้จากการเอาสีแดงจาง 10% ทับพื้นการ์ดของแต่ละแบรนด์ ผลคือแดงถูกพื้น
     กลืนจนออกม่วง/น้ำตาลและไม่เท่ากันสักแบรนด์ เปลี่ยนเป็นสีคงที่แบบเดียวกับ
     warning ไปเลย จะได้แดงชัดและเหมือนกันทุกแบรนด์
     (ต้องเอา --danger ออกจาก tint.css ด้วย ไม่งั้นโดนทับ) */
  --danger: hsl(358 60% 18%);
  /* โหมดมืดใช้ตัวอักษรขาว ไม่ใช่แดงอ่อน
     แดงอ่อน hsl(0 85% 79%) อ่านออกอยู่ (คอนทราสต์ 7.38) แต่พอวางคู่กับ Alert
     ตัวอื่นที่ตัวอักษรเกือบขาวหมด มันดูเป็นชมพูแปลกแยกออกมาตัวเดียว
     ความหมาย "อันตราย" สื่อด้วยพื้นแดงกับเส้นขอบแดงพอแล้ว */
  --danger-foreground: hsl(0 0% 100%);
  --danger-border: hsl(357 55% 34%);

  --brand: hsl(220 52.5% 15.7%);


  /* โหมดมืด — พื้นอ่อนกลายเป็นเข้ม ตัวอักษรกลายเป็นสว่าง
     สีทึบใช้เขียวสว่างขึ้นคู่กับตัวอักษรเข้ม ตรงกับที่ --primary ของทุกแบรนด์ทำอยู่แล้ว
     ส่วน amber ใช้ค่าเดียวกับโหมดสว่าง เพราะ Radix ตั้ง amber-9 ไว้เท่ากันทั้งสองโหมด */
  --success: #0f3815;
  --success-foreground: #47eb60;
  --success-border: #1d7c2b;
  /* โหมดมืดใช้ค่าเดียวกับโหมดสว่าง และ hover ก็ "เข้มลง" เหมือนกัน
     ผิดจากกฎปกติที่โหมดมืดต้องสว่างขึ้น แต่จำเป็น เพราะตัวอักษรเป็นสีขาว
     ถ้าทำให้เขียวสว่างขึ้นตอน hover คอนทราสต์จะตกต่ำกว่าเกณฑ์ทันที
     (เป็นเหตุผลเดียวกับที่ --primary-hover ของแบรนด์ส้มกลับด้าน) */
  --success-solid: #068919;
  --success-solid-foreground: #ffffff;
  --success-solid-hover: #057115;

  --warning-solid: hsl(43 100% 62%);
  --warning-solid-foreground: hsl(22 78% 20%);
  --warning-solid-hover: hsl(43 100% 68%);

  --border: hsl(217 33% 20%);
  --input: hsl(217 33% 20%);
  --ring: hsl(217 91% 60%);

  --chart-1: hsl(217 91% 60%);
  --chart-2: hsl(160 60% 45%);
  --chart-3: hsl(30 80% 55%);
  --chart-4: hsl(280 65% 60%);
  --chart-5: hsl(340 75% 55%);

  --sidebar: hsl(222 47% 11%);
  --sidebar-foreground: hsl(210 40% 98%);
  --sidebar-primary: hsl(217 91% 60%);
  --sidebar-primary-foreground: hsl(222 47% 11%);
  --sidebar-accent: hsl(217 33% 18%);
  --sidebar-accent-foreground: hsl(210 40% 98%);
  --sidebar-border: hsl(217 33% 20%);
  --sidebar-ring: hsl(217 91% 60%);
}

/* ============================================================
   Brand: GREEN  (สีเขียวมรกต + ฟอนต์ Prompt + มุมโค้งมากขึ้น)
   scope ด้วย [data-brand="green"]  ·  .dark = โหมดมืด
   ============================================================ */

[data-brand="green"] {
  --background: hsl(150 20% 99%);
  --foreground: hsl(160 30% 12%);

  --card: hsl(0 0% 100%);
  --card-foreground: hsl(160 30% 12%);

  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(160 30% 12%);

  --primary: hsl(160 84% 39%);
  --primary-foreground: hsl(0 0% 100%);

  --secondary: hsl(150 30% 94%);
  --secondary-foreground: hsl(160 30% 12%);

  --muted: hsl(150 25% 95%);
  --muted-foreground: hsl(160 12% 42%);

  --accent: hsl(150 40% 92%);
  --accent-foreground: hsl(160 30% 12%);

  --destructive: hsl(0 72% 51%);
  --destructive-foreground: hsl(0 0% 100%);

  /* สถานะ hover — โหมดสว่างให้ "เข้มขึ้น" (ลดค่า L) */
  --primary-hover: hsl(160 84% 34%);
  --secondary-hover: hsl(150 30% 91%);
  --accent-hover: hsl(150 40% 88%);
  --destructive-hover: hsl(0 72% 46%);


  /* พื้นผิวของ Alert แบบมีสี — ชุดเดียวกับ --card / --sidebar
     คือ <ชื่อพื้นผิว> + -foreground + -border

     ทุกค่าเป็น "สีทึบ" ไม่ใช่สีจางทับพื้น เพราะ Figma ผูก opacity ไว้กับ variable
