     ถ้าทำให้เขียวสว่างขึ้นตอน hover คอนทราสต์จะตกต่ำกว่าเกณฑ์ทันที
     (เป็นเหตุผลเดียวกับที่ --primary-hover ของแบรนด์ส้มกลับด้าน) */
  --success-solid: #068919;
  --success-solid-foreground: #ffffff;
  --success-solid-hover: #057115;

  --warning-solid: hsl(43 100% 62%);
  --warning-solid-foreground: hsl(22 78% 20%);
  --warning-solid-hover: hsl(43 100% 68%);

  --border: hsl(165 18% 20%);
  --input: hsl(165 18% 20%);
  --ring: hsl(158 64% 52%);

  --chart-1: hsl(158 64% 52%);
  --chart-2: hsl(200 70% 50%);
  --chart-3: hsl(40 85% 55%);
  --chart-4: hsl(280 60% 55%);
  --chart-5: hsl(350 70% 55%);

  --sidebar: hsl(165 28% 9%);
  --sidebar-foreground: hsl(150 20% 96%);
  --sidebar-primary: hsl(158 64% 52%);
  --sidebar-primary-foreground: hsl(165 30% 8%);
  --sidebar-accent: hsl(165 22% 18%);
  --sidebar-accent-foreground: hsl(150 20% 96%);
  --sidebar-border: hsl(165 18% 20%);
  --sidebar-ring: hsl(158 64% 52%);
}

/* ============================================================
   สไตล์ — แกนที่ปรับได้อิสระจากแบรนด์

   ใช้คู่กับไฟล์แบรนด์ ไม่ใช่แทนที่:
     <html data-brand="parich" data-radius="friendly" data-density="compact">

   ถ้าไม่ใส่ attribute จะใช้ค่าของแบรนด์นั้นตามปกติ ไฟล์นี้จึงเพิ่มเข้ามาได้
   โดยไม่กระทบของเดิมเลย

   ใช้ selector แบบ html[...] เพื่อให้ specificity (0,1,1) สูงกว่า
   [data-brand="..."] (0,1,0) จะได้ทับค่าของแบรนด์ได้แน่นอน
   ไม่ต้องพึ่งลำดับการ @import
   ============================================================ */

/* ---------------------------- ความโค้งของมุม ---------------------------- */
/* ตัวเลขในวงเล็บคือผลที่ได้จริง วัดจากเบราว์เซอร์
   ปุ่มใช้ rounded-md (= radius − 2px) · การ์ดใช้ rounded-xl (= radius + 4px) */

html[data-radius="sharp"] {
  --radius: 0rem; /* ปุ่ม 0px · การ์ด 4px */
}

html[data-radius="standard"] {
  --radius: 0.625rem; /* ปุ่ม 8px · การ์ด 14px */
}

html[data-radius="friendly"] {
  --radius: 1rem; /* ปุ่ม 14px · การ์ด 20px */
}

/* แคปซูล — ไม่ได้ตั้ง 9999px เพราะ rounded-md ถูกใช้ทั้งปุ่มและแผงดรอปดาวน์
   ถ้าดันสุด แผงจะกลายเป็นวงรี จึงตั้งค่าสูงพอที่เบราว์เซอร์จะจำกัดให้เอง
   (CSS ลดมุมโค้งลงอัตโนมัติเมื่อเกินครึ่งหนึ่งของด้านนั้น)
     ปุ่ม/ช่องกรอก สูง 27–45px -> กลายเป็นแคปซูลเต็ม
     แผง popover/dropdown สูง 200px+ -> ได้แค่มุมมน ไม่บิดเบี้ยว */
html[data-radius="pill"] {
  --radius: 1.75rem; /* ปุ่ม แคปซูล · การ์ด 32px */
}

/* ---------------------------- ความห่าง (density) ---------------------------- */
/* Tailwind v4 คำนวณ spacing utility ทุกตัวจาก --spacing
     .p-4 -> calc(var(--spacing) * 4)
     .h-9 -> calc(var(--spacing) * 9)
   เขียนทับตัวเดียวจึงเปลี่ยนระยะห่างทั้งระบบ

   เลือกค่าที่หารเป็นพิกเซลเต็ม (3 / 4 / 5px) ถ้าใช้เลขอย่าง 0.2rem
   จะได้ปุ่มสูง 28.7969px ซึ่งขอบจะเบลอบนจอความละเอียดปกติ

   หมายเหตุ: ไอคอนใช้ size-4 ซึ่งอิง --spacing เหมือนกัน จึงย่อขยายตามไปด้วย
   เป็นพฤติกรรมที่ตั้งใจ — ปุ่มแน่นควรมีไอคอนเล็กลงตามสัดส่วน */

html[data-density="compact"] {
  --spacing: 0.21875rem; /* 3.5px · ปุ่มสูง 31.5px · ไอคอน 14px */
}

html[data-density="standard"] {
  --spacing: 0.25rem; /* 4px  · ปุ่มสูง 36px · ไอคอน 16px */
}

html[data-density="comfortable"] {
  --spacing: 0.3125rem; /* 5px  · ปุ่มสูง 45px · ไอคอน 20px */
}

/* ============================================================
   ค่าเริ่มต้นของความโค้งและฟอนต์

   เดิมสองค่านี้อยู่ในไฟล์แบรนด์ ทำให้ "เลือกสี" ไปเปลี่ยนความโค้งกับฟอนต์ด้วย
   ทั้งที่มีดรอปดาวน์แยกอยู่แล้ว ย้ายออกมาไว้ที่เดียวเพื่อให้แบรนด์ = สีล้วน
   :root มี specificity (0,1,0) แพ้ html[data-radius=...] (0,1,1) แกนจึงทับได้
   ============================================================ */

:root {
  --radius: 0.625rem;
  --font-sans: var(--font-ibm-thai), ui-sans-serif, system-ui, sans-serif;
}

/* ============================================================
   แกนสไตล์: ฟอนต์ (data-font)

   ตัวแปร --font-* มาจาก next/font ในแอปที่ใช้งาน ไม่ได้มาจากแพ็กเกจนี้
   ถ้าโปรเจกต์ไหนไม่ได้ตั้งไว้ จะตกไปใช้ ui-sans-serif ตามลำดับในสแตก
   ============================================================ */

html[data-font="ibm"] {
  --font-sans: var(--font-ibm-thai), ui-sans-serif, system-ui, sans-serif; /* IBM Plex Sans Thai */
}

html[data-font="prompt"] {
  --font-sans: var(--font-prompt), ui-sans-serif, system-ui, sans-serif; /* Prompt */
}

html[data-font="sarabun"] {
  --font-sans: var(--font-sarabun), ui-sans-serif, system-ui, sans-serif; /* Sarabun */
}

